import{mkdtemp,mkdir,writeFile,readFile}from'node:fs/promises';import{pathToFileURL}from'node:url';import path from'node:path';
const runtime=process.env.PROGRAPH_OWNED_QUERY_RUNTIME??'/private/tmp/prograph-compatibility-cache-prototype-fygbbyco/dist/core/',load=name=>import(pathToFileURL(runtime+name+'.js').href);
const{SemanticStore}=await load('semantic/store'),{scanRepository}=await load('repository/repository'),{createIndexState}=await load('analysis/state'),{OwnedWriter,writeSyntaxBase,OWNED_PASS_VERSION}=await load('semantic/owned-projection'),{semanticKey,digest,canonical}=await load('semantic/model'),{readCompatibilitySnapshot}=await load('semantic/compatibility-snapshot');
const implementationDigests=Object.fromEntries(await Promise.all(['semantic/store','semantic/publication','semantic/compatibility-cache','semantic/compatibility-global','semantic/schema','query/compatibility-global-read','query/navigation'].map(async name=>[name,digest(await readFile(runtime+name+'.js'))])));const driverDigest=digest(await readFile(new URL(import.meta.url)));
const n=Number(process.argv[2]??20000);if(!Number.isSafeInteger(n)||n<100||n%100)throw Error('Use a positive multiple of 100 relationships');const size=n/100;
const root=await mkdtemp('/private/tmp/prograph-owned-publication-'),repo=root+'/repo',index=root+'/index';await mkdir(repo);await mkdir(index);await writeFile(repo+'/a.ts','export function caller(){}');await writeFile(repo+'/b.ts','export function target(){}');const{snapshot}=await scanRepository(repo,index);const stages=[];const store=new SemanticStore(index+'/semantic.sqlite',{measure:(name,ms)=>stages.push({name,ms})});
const context=semanticKey('analysis-context',[snapshot.repository.identity,OWNED_PASS_VERSION]),nodes=[{id:'repo',kind:'repository',name:'repo',qualifiedName:repo,adapter:'synthetic-workload',metadata:{}},...['a.ts','b.ts'].map(file=>({id:'file:'+file,kind:'file',name:file,qualifiedName:file,file,adapter:'synthetic-workload',language:'typescript',metadata:{}})),...['caller','target'].map((name,i)=>({id:name,kind:'function',name,qualifiedName:name,file:i?'b.ts':'a.ts',adapter:'synthetic-workload',language:'typescript',metadata:{}}))];
const base=writeSyntaxBase(store,snapshot,{nodes,edges:[],diagnostics:[],metadata:{}},context,digest('synthetic-owned-query-base'));
const prov={provider:'synthetic-owned-query-workload',version:'1',basis:'inference',method:'explicit-synthetic-projection',context,inputFingerprint:'benchmark'};
function token(name){const run=store.begin('support/'+name,context,name),key=semanticKey('support-token',[name]);store.addEntity(key,'artifact',{key});const claim=store.batch(run,()=>store.addFact(run,{predicate:'context.Project',context,subject:key,value:{syntheticToken:name},confidence:'exact',provenance:{...prov,inputFingerprint:name}}));store.seal(run,{status:'partial',scope:'synthetic graph workload'});return{run,claim}}
const a=token('a'),b=token('b'),pass=store.begin('analysis/pass:owned-query-workload@1',context,'one');store.selector(pass,'owned-query-workload','one');const guardKey=semanticKey('support-token',['guard']);store.addEntity(guardKey,'artifact',{key:guardKey});const guard=store.batch(pass,()=>store.addFact(pass,{predicate:'support.Conjunction',context,subject:guardKey,value:{syntheticGuard:true},confidence:'exact',provenance:{...prov,inputFingerprint:'one'},supports:[[{claim:base.nodeClaims.get('caller')},{claim:a.claim}],[{claim:base.nodeClaims.get('caller')},{claim:b.claim}]]}));store.seal(pass,{status:'partial',pass:'owned-query-workload',dependencies:[],version:'1',scope:'Synthetic query projection shape, not compiler qualification'});
const inputNodes=new Map(base.nodeClaims);inputNodes.set('caller',guard);const owners=[];
function shard(i,revision){const fingerprint=digest(canonical([i,revision])),run=store.begin('analysis/pass:owned-query-workload@1/shard:'+String(i).padStart(3,'0'),context,fingerprint);const writer=new OwnedWriter(store,run,snapshot,{...prov,inputFingerprint:fingerprint},{key:'owned-query-workload',digest:'one'},base.fileClaims,inputNodes);const edges=Array.from({length:size},(_,j)=>({id:'edge:'+String(i*size+j).padStart(8,'0'),source:'caller',target:'target',kind:'calls',confidence:'resolved',evidence:[{file:'a.ts',line:1,adapter:'synthetic-workload'}],metadata:{revision}}));writer.write({nodes:[],edges,diagnostics:[],metadata:{}});store.seal(run,{status:'partial',pass:'owned-query-workload',dependencies:[],version:'1',ownershipShard:'synthetic segment',scope:'Synthetic graph projection'});return run}
const stagingStart=performance.now();for(let i=0;i<100;i++)owners.push(shard(i,0));const stagingMs=performance.now()-stagingStart;
function report(edges){const generatedAt=new Date().toISOString(),manifest={schemaVersion:'1.2.0',toolVersion:'0.3.0',repositoryRoot:repo,repositoryIdentity:snapshot.repository.identity,generatedAt,adapterRuns:[],enabledAdapters:[],scannedFileCount:2,excludedFileCount:0,nodeCount:nodes.length,edgeCount:edges,diagnosticCount:0,analysisDuration:0,semanticCore:{format:2,status:'partial',durationMs:0,reason:'Synthetic graph projection workload; no compiler/provider/LOC qualification'}};const{files,...stateHeader}=createIndexState(snapshot,manifest);return{manifest,stateHeader}}
let parent;const samples=[];
function publish(label,selected,edges){stages.length=0;const start=performance.now();const id=store.publish(selected,parent,[],report(edges));const durationMs=performance.now()-start;parent=id;const cache=JSON.parse(store.sql("SELECT value FROM cg_meta WHERE key='work'").get().value),queries=JSON.parse(store.sql("SELECT value FROM cq_meta WHERE key='work'").get().value);const count=store.sql('SELECT COUNT(*) n FROM edges').get().n;if(count!==edges)throw Error('Projected edge count mismatch');const supported=store.sql('SELECT COUNT(*) n FROM cg_current c WHERE NOT EXISTS(SELECT 1 FROM sc_active a WHERE a.snapshot=? AND a.claim=c.claim)').get(id).n;if(supported)throw Error('Unsupported current payload');samples.push({label,snapshot:id,durationMs,stages:[...stages],cache,queries,edges:count})}
const fixed=[...base.runs,pass];publish('full-first',[...fixed,...owners,a.run,b.run],n);const first=parent;store.pinSnapshot(first,'benchmark-history');publish('no-op',[...fixed,...owners,a.run,b.run],n);
for(const changed of[1,10,100]){const start=performance.now();for(let i=0;i<changed;i++)owners[i]=shard(i,changed);const preparationMs=performance.now()-start;publish(changed+' changed partitions',[...fixed,...owners,a.run,b.run],n);samples.at(-1).stagingMs=preparationMs}
publish('remove first support, alternative preserves all edges',[...fixed,...owners,b.run],n);publish('remove last support, invalidate all edges',[...fixed,...owners],0);
const historical=store.db.transaction(()=>readCompatibilitySnapshot(store.db,first))();if(historical.graph.edges.length!==n)throw Error('Historical projected relationships changed');store.collectGarbage({keep:1});if(!store.sql('SELECT 1 FROM sc_snapshots WHERE id=?').get(first))throw Error('Pinned history collected');
const receipt={format:1,implementationDigests,driverDigest,scope:'Synthetic owned compatibility graph publication, 100 edge shards and one high-fanout OR-of-AND support guard. This does not replace the original 1M SCIP occurrence/claim benchmark and is not LOC or producer qualification.',node:process.version,platform:process.platform,arch:process.arch,root,shape:{nodes:nodes.length,relationships:n,changedShardRows:size,edgeShards:100},stagingMs,samples,durability:{journal:store.db.pragma('journal_mode',{simple:true}),synchronous:store.db.pragma('synchronous',{simple:true})},historicalEdges:historical.graph.edges.length,integrity:store.db.pragma('integrity_check',{simple:true}),foreignKeys:store.db.pragma('foreign_key_check'),methodology:'Serial full first/no-op/1/10/100 changed partition publications through the normal publisher. Complete support validation, required navigation/membership, compatibility/query construction, pointer and FULL commit are included. Staging reported separately; no required work is timed as pointer-only. Single trial, OS cache not evicted; not p95 or cold/power-loss evidence.'};store.close();await writeFile(process.argv[3]??'/private/tmp/prograph-owned-query-publication-'+n+'.json',JSON.stringify(receipt,null,2));console.log(JSON.stringify(receipt,null,2));
